import{_ as r,c as t,o as a,a5 as o}from"./chunks/framework.DuCYAsAJ.js";const f=JSON.parse('{"title":"Front-API 网关","description":"","frontmatter":{"title":"Front-API 网关","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#2","branch":"main","level":0,"order":2},"headers":[],"relativePath":"posts/projects/zfeed/02-front-api-gateway/index.md","filePath":"posts/projects/zfeed/02-front-api-gateway/index.md","lastUpdated":1779632679000}'),i={name:"posts/projects/zfeed/02-front-api-gateway/index.md"};function n(l,e,c,d,p,h){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="front-api-网关" tabindex="-1">Front-API 网关 <a class="header-anchor" href="#front-api-网关" aria-label="Permalink to &quot;Front-API 网关&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/.gitignore" target="_blank" rel="noreferrer">.gitignore</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/search/search.api" target="_blank" rel="noreferrer">app/front/doc/search/search.api</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/front.go" target="_blank" rel="noreferrer">app/front/front.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/config/config.go" target="_blank" rel="noreferrer">app/front/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/logoutlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/user/logoutlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/userloginstatusauthmiddleware.go" target="_blank" rel="noreferrer">app/front/internal/middleware/userloginstatusauthmiddleware.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/svc/servicecontext.go" target="_blank" rel="noreferrer">app/front/internal/svc/servicecontext.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/types/types.go" target="_blank" rel="noreferrer">app/front/internal/types/types.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/proto/search.proto" target="_blank" rel="noreferrer">app/rpc/search/proto/search.proto</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/search/search.pb.go" target="_blank" rel="noreferrer">app/rpc/search/search/search.pb.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/logoutlogic.go" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/logoutlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/go.sum" target="_blank" rel="noreferrer">go.sum</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/pkg/errorx/error.go" target="_blank" rel="noreferrer">pkg/errorx/error.go</a></li></ul></details><p><code>front-api</code> 服务是 zfeed 生态中所有客户端流量的统一入口。它是一个基于 <code>go-zero</code> 框架构建的 HTTP 网关，负责请求路由、协议转换（HTTP 到 gRPC）、认证，以及从多个下游微服务聚合数据。</p><h3 id="网关角色与架构" tabindex="-1">网关角色与架构 <a class="header-anchor" href="#网关角色与架构" aria-label="Permalink to &quot;网关角色与架构&quot;">​</a></h3><p>网关作为门面层存在，对客户端屏蔽微服务拓扑的复杂性。它通过 <code>ServiceContext</code> 初始化并维护到各主要 RPC 服务的 gRPC 客户端连接。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/svc/servicecontext.go#L25-L39" target="_blank" rel="noreferrer">app/front/internal/svc/servicecontext.go#25-39</a></p><p>核心职责：</p><ul><li>请求路由：根据 API 定义将 HTTP 请求分发到对应的 logic handler。</li><li>RPC 聚合：编排对 <code>UserRpc</code>、<code>ContentRpc</code>、<code>CountRpc</code> 等服务的调用，构建复杂响应。</li><li>中间件执行：在进入业务逻辑之前执行安全策略和会话管理。</li><li>错误映射：通过全局错误处理器，将内部 gRPC/业务错误转换为标准 HTTP 状态码。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/front.go#L31-L33" target="_blank" rel="noreferrer">app/front/front.go#31-33</a></li></ul><h3 id="服务上下文与依赖" tabindex="-1">服务上下文与依赖 <a class="header-anchor" href="#服务上下文与依赖" aria-label="Permalink to &quot;服务上下文与依赖&quot;">​</a></h3><p><code>ServiceContext</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/svc/servicecontext.go#L25-L39" target="_blank" rel="noreferrer">app/front/internal/svc/servicecontext.go#25-39</a> 是网关的依赖注入容器。它保存 logic 层需要的 gRPC 客户端和共享基础设施句柄。</p><table tabindex="0"><thead><tr><th>依赖</th><th>代码实体</th><th>作用</th></tr></thead><tbody><tr><td>用户服务</td><td><code>UserRpc</code></td><td>认证、资料和用户管理。</td></tr><tr><td>内容服务</td><td><code>ContentRpc</code></td><td>文章/视频生命周期与元数据。</td></tr><tr><td>Feed 服务</td><td><code>FeedRpc</code></td><td>获取推荐 Feed 和关注 Feed。</td></tr><tr><td>互动服务</td><td><code>LikeRpc</code>、<code>CommentRpc</code> 等</td><td>社交动作，例如点赞、评论、关注。</td></tr><tr><td>搜索服务</td><td><code>SearchRpc</code></td><td>面向用户和内容的全文搜索。</td></tr><tr><td>缓存</td><td><code>Redis</code></td><td>会话存储和网关级共享缓存。</td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/svc/servicecontext.go#L25-L39" target="_blank" rel="noreferrer">app/front/internal/svc/servicecontext.go#25-39</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/config/config.go#L12-L24" target="_blank" rel="noreferrer">app/front/internal/config/config.go#12-24</a></p><h3 id="请求流与实体映射" tabindex="-1">请求流与实体映射 <a class="header-anchor" href="#请求流与实体映射" aria-label="Permalink to &quot;请求流与实体映射&quot;">​</a></h3><p>下图展示进入网关的 HTTP 请求如何被处理，并映射到下游 RPC 实体。</p><p>请求转换流程</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/handler/handler.go" target="_blank" rel="noreferrer">app/front/internal/handler/handler.go</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/user/logoutlogic.go#L33-L53" target="_blank" rel="noreferrer">app/front/internal/logic/user/logoutlogic.go#33-53</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/user/internal/logic/logoutlogic.go#L28-L38" target="_blank" rel="noreferrer">app/rpc/user/internal/logic/logoutlogic.go#28-38</a></p><h3 id="中间件与安全" tabindex="-1">中间件与安全 <a class="header-anchor" href="#中间件与安全" aria-label="Permalink to &quot;中间件与安全&quot;">​</a></h3><p>网关通过 <code>rest.Middleware</code> 实现两种主要认证模式。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/svc/servicecontext.go#L37-L38" target="_blank" rel="noreferrer">app/front/internal/svc/servicecontext.go#37-38</a></p><ol><li>严格认证（<code>UserLoginStatusAuthMiddleware</code>）：写操作（发布、点赞等）必须经过该认证。它会提取 Bearer token，基于 Redis 校验 token，并把 <code>userID</code> 注入请求上下文。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/middleware/userloginstatusauthmiddleware.go#L29-L47" target="_blank" rel="noreferrer">app/front/internal/middleware/userloginstatusauthmiddleware.go#29-47</a></li><li>可选认证（<code>OptionalLoginMiddleware</code>）：用于读操作（Feed、搜索等）。它会尝试识别用户，以便提供个性化状态（例如 <code>IsLiked</code>），但在没有 token 时也允许匿名访问。</li></ol><p>会话生命周期和基于 Lua 的校验细节请参阅<a href="./01-authentication-and-session-management.html">认证与会话管理</a>。</p><h3 id="api-表面与子系统" tabindex="-1">API 表面与子系统 <a class="header-anchor" href="#api-表面与子系统" aria-label="Permalink to &quot;API 表面与子系统&quot;">​</a></h3><p>API 按功能域拆分，每个功能域由对应的 logic 分组处理：</p><ul><li>用户管理：注册、登录和个人资料操作。详情请参阅<a href="./02-user-api-handlers.html">用户 API 处理器</a>。</li><li>内容与 Feed：发布文章/视频，并消费多种 Feed 类型（推荐、关注、用户）。详情请参阅<a href="./03-content-and-feed-api-handlers.html">内容与 Feed API 处理器</a>。</li><li>互动与搜索：社交信号（点赞、评论）和全文搜索能力。详情请参阅<a href="./04-interaction-and-search-api-handlers.html">互动与搜索 API 处理器</a>。</li></ul><p>网关接口概览</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/types/types.go" target="_blank" rel="noreferrer">app/front/internal/types/types.go</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/search/search.api#L59-L71" target="_blank" rel="noreferrer">app/front/doc/search/search.api#59-71</a></p><h3 id="子页面" tabindex="-1">子页面 <a class="header-anchor" href="#子页面" aria-label="Permalink to &quot;子页面&quot;">​</a></h3><ul><li><a href="./01-authentication-and-session-management.html">认证与会话管理</a>：深入讲解 Bearer token 流程、Redis 会话存储和中间件逻辑。</li><li><a href="./02-user-api-handlers.html">用户 API 处理器</a>：用户资料、粉丝列表和账号管理的实现细节。</li><li><a href="./03-content-and-feed-api-handlers.html">内容与 Feed API 处理器</a>：网关如何处理内容创建，并为 UI 聚合 Feed 数据。</li><li><a href="./04-interaction-and-search-api-handlers.html">互动与搜索 API 处理器</a>：社交互动路由与复杂搜索查询执行细节。</li></ul>',26)])])}const g=r(i,[["render",n]]);export{f as __pageData,g as default};
